// Flatten Notion's property shape back into plain fields.
const text = p => p?.rich_text?.[0]?.plain_text ?? '';
const pages = $input.first().json.results ?? [];

const jobs = pages.map(p => {
  const props = p.properties ?? {};
  return {
    title: props['Title']?.title?.[0]?.plain_text ?? 'Untitled',
    company: text(props['Company']),
    location: text(props['Location']),
    url: props['URL']?.url ?? '',
    score: props['Score']?.number ?? 0,
    salaryBand: props['Salary Band']?.select?.name ?? 'Unknown',
    salaryMin: props['Salary Min']?.number ?? null,
    salaryMax: props['Salary Max']?.number ?? null,
    reason: text(props['Why']),
    source: props['Source']?.select?.name ?? '',
  };
});

if (jobs.length === 0) return [];
return [{ json: { jobs, count: jobs.length } }];

const { jobs, count } = $input.first().json;
const target = jobs.filter(j => j.salaryBand === 'Target (100k+)');

const row = j => `<tr>
  <td style="padding:8px;border-bottom:1px solid #eee"><b>${j.score}</b></td>
  <td style="padding:8px;border-bottom:1px solid #eee"><a href="${j.url}">${j.title}</a><br><small>${j.company} - ${j.location} - ${j.source}</small></td>
  <td style="padding:8px;border-bottom:1px solid #eee">${j.salaryBand}<br><small>${j.salaryMin ?? '?'} - ${j.salaryMax ?? '?'}</small></td>
  <td style="padding:8px;border-bottom:1px solid #eee"><small>${j.reason}</small></td>
</tr>`;

const html = `<h2>This week: ${count} role${count === 1 ? '' : 's'}</h2>
<p>${target.length} in the 100k+ band.</p>
<table style="border-collapse:collapse;font-family:sans-serif;font-size:14px">
<tr><th align="left">Score</th><th align="left">Role</th><th align="left">Salary</th><th align="left">Why</th></tr>
${jobs.map(row).join('')}
</table>`;

return [{ json: { html, count } }];
